import type { ComponentProps, ReactNode } from 'react';
import { Card, CardAction, CardContent, CardHeader, CardTitle } from '../ui/card';
import { cn } from '../../utils';

export interface PanelProps extends Omit<ComponentProps<typeof Card>, 'title'> {
  title?: ReactNode;
  /** Right-aligned header controls: interval pickers, layout toggles. */
  actions?: ReactNode;
  children?: ReactNode;
  /** Pad the body. Leave off for tables and ladders that own their padding. */
  padded?: boolean;
  /** Drop the frame so the panel can sit inside existing chrome. */
  flush?: boolean;
  /** Let the body scroll instead of growing the panel. */
  scroll?: boolean;
  contentClassName?: string;
}

/**
 * The frame every widget sits in: fixed header, flexible body.
 *
 * `min-h-0` on the body is the part that matters - without it a chart panel
 * refuses to shrink inside a flex or grid terminal layout and pushes the whole
 * page open instead.
 */
export function Panel({
  title,
  actions,
  children,
  padded = false,
  flush = false,
  scroll = false,
  className,
  contentClassName,
  ...props
}: PanelProps) {
  return (
    <Card
      data-slot="panel"
      className={cn(
        'min-h-0 min-w-0 gap-0 overflow-hidden',
        flush && 'rounded-none border-0 bg-transparent shadow-none',
        className,
      )}
      {...props}
    >
      {(title || actions) && (
        <CardHeader className="shrink-0">
          {title && <CardTitle>{title}</CardTitle>}
          {actions && <CardAction>{actions}</CardAction>}
        </CardHeader>
      )}
      <CardContent
        className={cn(
          'flex min-h-0 flex-1 flex-col',
          padded && 'p-3',
          scroll && 'overflow-auto',
          contentClassName,
        )}
      >
        {children}
      </CardContent>
    </Card>
  );
}

import type { ComponentProps } from 'react';
import { cn } from '../../utils';

/** shadcn/ui Card. `Panel` builds the trading chrome on top of this. */
function Card({ className, ...props }: ComponentProps<'div'>) {
  return (
    <div
      data-slot="card"
      className={cn(
        'bg-card text-card-foreground flex flex-col rounded-xl border shadow-sm',
        className,
      )}
      {...props}
    />
  );
}

function CardHeader({ className, ...props }: ComponentProps<'div'>) {
  return (
    <div
      data-slot="card-header"
      className={cn(
        'flex items-center gap-2 border-b px-3 py-2 [.border-b]:pb-2',
        className,
      )}
      {...props}
    />
  );
}

function CardTitle({ className, ...props }: ComponentProps<'div'>) {
  return (
    <div
      data-slot="card-title"
      className={cn(
        'text-muted-foreground text-xs font-semibold tracking-wider uppercase',
        className,
      )}
      {...props}
    />
  );
}

function CardAction({ className, ...props }: ComponentProps<'div'>) {
  return (
    <div
      data-slot="card-action"
      className={cn('ml-auto flex items-center gap-1.5', className)}
      {...props}
    />
  );
}

function CardContent({ className, ...props }: ComponentProps<'div'>) {
  return <div data-slot="card-content" className={cn('min-h-0', className)} {...props} />;
}

function CardFooter({ className, ...props }: ComponentProps<'div'>) {
  return (
    <div
      data-slot="card-footer"
      className={cn('flex items-center border-t px-3 py-2', className)}
      {...props}
    />
  );
}

export { Card, CardHeader, CardTitle, CardAction, CardContent, CardFooter };

import { clsx, type ClassValue } from 'clsx';
import { twMerge } from 'tailwind-merge';

/**
 * Merge Tailwind classes with later ones winning - the same `cn` shadcn/ui
 * uses, so a consumer can override any class on any component by passing
 * `className`, with no specificity war.
 */
export function cn(...inputs: ClassValue[]) {
  return twMerge(clsx(inputs));
}
